    if ($Task -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') { Stop-WithError "-Task must be a slug (letters, digits, dot, dash, underscore)." }
    # the task's last ledger entry (the highest n) - its allowlisted details are the context; none
